def _psi_direct(x: int) -> float:
    primes = _sieve(int(x))
    total = 0.0
    for p in primes:
        power = p
        while power <= x:
            total += math.log(p)
            power *= p
    return total

def _sieve(limit: int) -> list[int]:
    if limit < 2:
        return []
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for p in range(2, int(limit ** 0.5) + 1):
        if sieve[p]:
            step = p
            sieve[p * p :: step] = [False] * ((limit - p * p) // step + 1)

