def chunk_text(text: str, chunk_size: int) -> Iterator[str]:
    """Yield successive ``chunk_size``-sized pieces from ``text``."""

    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive")
    for start in range(0, len(text), chunk_size):
