def _format_hashrate(value: float | None) -> str:
    if value is None:
        return "—"
    units = ["H/s", "kH/s", "MH/s", "GH/s", "TH/s"]
    amount = value
    index = 0
    while amount >= 1000 and index < len(units) - 1:
        amount /= 1000
        index += 1

def _temperature_intent(temp: float | None) -> str | None:
    if temp is None:
