    if temp >= 85:
        return "critical"
    if temp >= 80:
        return "warning"
    return "good"

def _relative_time(value: datetime | None) -> str:
    if value is None:
        return "—"
    if value.tzinfo is not None:
        ref = datetime.now(timezone.utc)
        moment = value.astimezone(timezone.utc)
    else:
        ref = datetime.utcnow()
        moment = value

