def tf(tokens: Iterable[str]) -> Dict[str, float]:
    counts: Dict[str, float] = {}
    total = 0.0
    for token in tokens:
        counts[token] = counts.get(token, 0.0) + 1.0
        total += 1.0
    if total == 0:
        return {}
    return {token: freq / total for token, freq in counts.items()}

