def _random_regular_graph(n: int, degree: int, seed: int | None = None) -> List[tuple[int, int]]:
    rng = random.Random(seed)
    edges = set()
    while len(edges) < n * degree // 2:
        a, b = rng.randrange(n), rng.randrange(n)
        if a == b:
            continue
        edge = tuple(sorted((a, b)))
        edges.add(edge)

