def _quantile(sorted_vals: List[int], q: float) -> int:
    if not sorted_vals:
        return 0
    idx = (len(sorted_vals) - 1) * q
    lower = int(idx)
    upper = min(lower + 1, len(sorted_vals) - 1)
    frac = idx - lower
    return int(sorted_vals[lower] + (sorted_vals[upper] - sorted_vals[lower]) * frac)

