    tree_a = cKDTree(a)
    tree_b = cKDTree(b)
    dist_ab, _ = tree_a.query(b, k=1)
    dist_ba, _ = tree_b.query(a, k=1)
    return float(max(dist_ab.max(), dist_ba.max()))


