def _format_outline(points: Iterable[List[float]]) -> str:
    moves = ["G21 ; metric"]
    for idx, (x, y) in enumerate(points):
        prefix = "G0" if idx == 0 else "G1"
        moves.append(f"{prefix} X{x:.3f} Y{y:.3f}")
    moves.append("G1 X0 Y0")
    moves.append("M2")
    return "\n".join(moves)

