    label = f" – {step.label}" if step.label else ""
    delay = f", delay={step.delay:.2f}s" if step.delay else ""
    wait = f", wait={step.wait:.2f}s" if step.wait else ""
    return f"Step {step.index}: topic='{step.topic}'{label}{delay}{wait}"


