def _tokenize_for_hash(text: str, ngram_size: int) -> List[int]:
    if len(text) < ngram_size:
        return [hash(text)]
    ngrams = (text[i : i + ngram_size] for i in range(len(text) - ngram_size + 1))
    return [hash(ngram) for ngram in ngrams]


