def majority(values: Iterable[TruthValue]) -> TruthValue:
    """Return majority truth value, UNKNOWN on tie."""
    counts = Counter(values)
    if not counts:
        return TruthValue.UNKNOWN
    best = counts.most_common()
    if len(best) > 1 and best[0][1] == best[1][1]:
        return TruthValue.UNKNOWN
    return best[0][0]

