def collatz_step(n: int) -> int:
    if n % 2 == 0:
        return n // 2
    # 3n+1 then compress factors of 2
    n = 3 * n + 1
    # remove all trailing zeros in binary (i.e., divide by 2^k)
    return n >> (
        (n & -n).bit_length() - 1
    )  # bit trick: count trailing zeros via bit_length of lowbit

