  if(!fs.existsSync(p)) return [] as { hash: string; file: string }[];
  const raw = fs.readFileSync(p,'utf8').trim().split('\n');
  return raw.map(line => {
    // Format: <sha>  <path>
    const [hash, ...rest] = line.split(/\s+/);
    const file = rest.join(' ').trim();
    return { hash, file };
  }).filter(x=>x.hash && x.file);

}

