export function deterministicShuffle<T>(values: T[], seed: number | string): T[] {
  const rng = createSeededRng(seed);
  const copy = values.slice();
  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(rng() * (i + 1));
    const tmp = copy[i];
    copy[i] = copy[j];
    copy[j] = tmp;
  }

}

