function dedupeTasks(tasks: PlannedTask[]): PlannedTask[] {
  const seen = new Map<string, PlannedTask>();
  for (const task of tasks) {
    if (!seen.has(task.id)) {
      seen.set(task.id, task);
    }
  }
  return Array.from(seen.values());
}

