function verifySignature(req) {
  const signature = req.header('X-Hub-Signature-256');
  if (!signature) return false;
  const body = JSON.stringify(req.body);
  const hmac = crypto.createHmac('sha256', GITHUB_WEBHOOK_SECRET);
