export function rateLimit(key: string, limit: number = LIMIT) {
  const now = Date.now();
  const bucket = buckets.get(key);
  if (bucket && now < bucket.reset) {
    if (bucket.count >= limit) return false;
    bucket.count += 1;
    return true;
  }
  buckets.set(key, { count: 1, reset: now + WINDOW_MS });

}

