  return new Promise((resolve)=>{
    const socket = tls.connect(443, domain, {servername:domain}, ()=>{
      const cert = socket.getPeerCertificate();
      const exp = new Date(cert.valid_to);
      const days = Math.ceil((exp - Date.now())/86400000);
      socket.end();
      resolve(days);
    });

