  fireOnTick?: () => Promise<void> | void;
};

async function enqueueHeartbeat(): Promise<void> {
  const payload: HeartbeatPayload = { ts: Date.now() };
  await getQueue('heartbeat').add('heartbeat', payload);
  logger.info({ payload }, 'heartbeat queued');
}

