  if (lw.endsWith('ed')) return lw.slice(0, -2);
  if (lw.endsWith('ing')) return lw.slice(0, -3);
  if (lw.endsWith('es')) return lw.slice(0, -2);
  if (lw.endsWith('s') && !lw.endsWith('ss')) return lw.slice(0, -1);
  return lw;
}

